def file_exists(name: str) -> bool:
    return (LOG_DIR / name).exists()


def read_phase3_summary() -> List[Dict[str, str]]:
    path = LOG_DIR / "phase3_summary.csv"
    if not path.exists():
        return []
    rows: List[Dict[str, str]] = []
    with open(path, newline="", encoding="utf-8", errors="replace") as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append({k: (v or "") for k, v in row.items()})
    return rows


def status_counts(rows: List[Dict[str, str]]) -> Dict[str, int]:
    counts = {"ALLOW": 0, "DENY": 0, "QUARANTINE": 0, "PASS": 0, "FAIL": 0}
    for row in rows:
        decision = row.get("actual_decision", "").upper()
        status = row.get("status", "").upper()
        if decision in counts:
            counts[decision] += 1
        if status in counts:
            counts[status] += 1
    return counts


def phase_file_score(files: List[str]) -> Tuple[int, int]:
    existing = sum(1 for name in files if file_exists(name))
    return existing, len(files)


def phase3_test_lookup(rows: List[Dict[str, str]]) -> Dict[str, Dict[str, str]]:
    lookup: Dict[str, Dict[str, str]] = {}
    for row in rows:
        test_name = row.get("test_name", "")
        if test_name:
            lookup[test_name] = row
    return lookup


def build_common_comparison(rows: List[Dict[str, str]]) -> List[Dict[str, str]]:
    p3_lookup = phase3_test_lookup(rows)
    comparison = []
    for item in COMMON_TESTS:
        p3 = p3_lookup.get(item["phase3_test"], {})
        comparison.append({
            "scenario": item["scenario"],
            "p1_available": file_exists(item["phase1_file"]),
            "p2_available": file_exists(item["phase2_file"]),
            "p2_label": item.get("p2_label", "Available"),
            "p2_status": item.get("p2_status", "pass"),
            "p3_status": p3.get("status", "Missing"),
            "p3_decision": p3.get("actual_decision", "Missing"),
            "p1_note": item["p1_note"],
            "p2_note": item["p2_note"],
            "p3_note": item["p3_note"],
        })
    return comparison


def list_log_files() -> List[Dict[str, str]]:
    if not LOG_DIR.exists():
        return []
    files = []
    for path in sorted(LOG_DIR.rglob("*")):
        if path.is_file():
            rel = path.relative_to(LOG_DIR).as_posix()
            category = "Raw / Result"
            if "anonym" in rel.lower():
                category = "Anonymized"
            elif path.suffix == ".pcap":
                category = "PCAP Capture"
            elif path.name.endswith("_capture.txt"):
                category = "Converted Capture"
            elif path.suffix == ".csv":
                category = "Summary CSV"
            files.append({
                "name": rel,
                "category": category,
                "size": f"{path.stat().st_size / 1024:.1f} KB",
            })
    return files


def dashboard_context() -> Dict[str, object]:
    rows = read_phase3_summary()
    counts = status_counts(rows)
    p1_existing, p1_total = phase_file_score(PHASE1_FILES)
    p2_existing, p2_total = phase_file_score(PHASE2_FILES)
    p3_total = len(rows)
    p3_pass = counts["PASS"]

    phases = [
    {
        "phase": "Phase 1",
        "model": "Baseline Network",
        "risk": "High",
        "summary": "No firewall or access policy. Used to show the weakness of flat internal trust.",
        "score": 15,
        "evidence": "Low security effectiveness",
    },
    {
        "phase": "Phase 2",
        "model": "Traditional Firewall",
        "risk": "Medium",
        "summary": "Static filtering and rate limiting reduce some attacks but do not evaluate identity or behavior risk.",
        "score": 55,
        "evidence": "Partial security improvement",
    },
    {
        "phase": "Phase 3",
        "model": "Zero Trust",
        "risk": "Low",
        "summary": "Identity, behavior, risk, policy rules, quarantine, and anonymized evidence are applied.",
        "score": 90,
        "evidence": "Strongest security effectiveness",
    },
]

    return {
        "rows": rows,
        "counts": counts,
        "phases": phases,
        "common_comparison": build_common_comparison(rows),
        "policy_matrix": POLICY_MATRIX,
        "attack_stories": ATTACK_STORIES,
        "log_files": list_log_files(),
        "log_dir": str(LOG_DIR),
    }


