@app.route("/log/<path:filename>")
def view_log(filename: str):
    # Protect against path traversal
    target = (LOG_DIR / filename).resolve()

    try:
        target.relative_to(LOG_DIR.resolve())
    except ValueError:
        abort(404)

    if not target.exists() or not target.is_file():
        abort(404)

    if target.suffix == ".pcap":
        return send_from_directory(LOG_DIR, filename, as_attachment=True)

    text = target.read_text(encoding="utf-8", errors="replace")

    if len(text) > 120_000:
        text = text[:120_000] + "\n\n[Output truncated for dashboard viewing.]"

    return render_template("log_view.html", filename=filename, content=html.escape(text))


